CREATE TABLE editor_asset_migrations(version INTEGER PRIMARY KEY CHECK(version=2));
CREATE TABLE editor_assets(asset_id TEXT PRIMARY KEY CHECK(length(asset_id)=36),attempt_id TEXT NOT NULL UNIQUE CHECK(length(attempt_id)=64),document_id TEXT NOT NULL REFERENCES editor_documents(document_id),generation TEXT NOT NULL CHECK(length(generation)=64),object_key TEXT NOT NULL UNIQUE CHECK(length(object_key)=80),status TEXT NOT NULL CHECK(status IN ('pending','ready','terminal')),reserved_bytes BIGINT NOT NULL CHECK(reserved_bytes BETWEEN 1 AND 10485760),byte_size BIGINT NOT NULL CHECK(byte_size BETWEEN 0 AND reserved_bytes),media_type TEXT NOT NULL CHECK(media_type IN ('image/png','image/jpeg','image/webp')),safe_name TEXT NOT NULL CHECK(length(safe_name) BETWEEN 1 AND 128),sha256 TEXT NOT NULL CHECK(length(sha256) IN (0,64)),lease_until BIGINT NOT NULL CHECK(lease_until BETWEEN 0 AND 9007199254740991),next_probe_at BIGINT NOT NULL CHECK(next_probe_at BETWEEN 0 AND 9007199254740991),claim_token TEXT NOT NULL CHECK(length(claim_token) IN (0,64)),created_at BIGINT NOT NULL CHECK(created_at BETWEEN 1 AND 9007199254740991),CHECK(status<>'ready' OR (byte_size>0 AND length(sha256)=64)));
CREATE INDEX editor_assets_document ON editor_assets(document_id,status);
CREATE INDEX editor_assets_probe ON editor_assets(status,next_probe_at,lease_until);
CREATE FUNCTION editor_assets_document_fence() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'document-tombstone-required'; END IF; IF NEW.deleted=1 OR NEW.generation<>OLD.generation THEN UPDATE editor_assets SET status='terminal',next_probe_at=0 WHERE document_id=NEW.document_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER editor_assets_document_fence AFTER UPDATE OF generation,deleted ON editor_documents FOR EACH ROW EXECUTE FUNCTION editor_assets_document_fence();
CREATE TRIGGER editor_assets_document_remove BEFORE DELETE ON editor_documents FOR EACH ROW EXECUTE FUNCTION editor_assets_document_fence();
INSERT INTO editor_asset_migrations(version) VALUES(2);
